item.ns2:encoded:
/* Puzzle Path mobile home refinements */
@media (max-width: 600px) {
  body.home .elementor-heading-title {
    overflow-wrap: normal;
    word-break: normal;
  }
  body.home h1.elementor-heading-title {
    font-size: 34px;
    line-height: 1.12;
  }
  body.home h2.elementor-heading-title {
    font-size: 28px;
    line-height: 1.18;
  }
  body.home h3.elementor-heading-title {
    font-size: 21px;
    line-height: 1.25;
  }
}
/* Puzzle Path mobile overflow fix */
@media (max-width: 600px) {
  body.home,
  body.home #page,
  body.home #content,
  body.home .entry-content {
    max-width: 100%;
    overflow-x: hidden;
  }

  body.home .elementor-widget-image,
  body.home .elementor-widget-image .elementor-widget-container,
  body.home .elementor-widget-image img {
    max-width: 100% !important;
  }

  body.home .elementor-widget-image img {
    width: 100% !important;
    height: auto !important;
    object-fit: cover;
  }

  body.home .elementor-element {
    min-width: 0;
  }
}


/* Responsive adventure listing */
@media(max-width:1100px){
body .puzzle-adventures-container .adventures-grid{display:grid!important;grid-template-columns:minmax(0,1fr)!important;width:100%!important;max-width:500px!important;min-width:0;gap:20px;}
.puzzle-adventures-container .adventures-grid-wrap,.puzzle-adventures-container .adventure-card,.puzzle-adventures-container .adventure-content{min-width:0;max-width:100%;box-sizing:border-box;}
.puzzle-adventures-container .adventure-card{width:100%;height:auto;}
.puzzle-adventures-container .info-line>span:not(.info-icon){min-width:0;overflow-wrap:anywhere;}
.puzzle-adventures-container .info-line{flex-wrap:wrap;}
.puzzle-adventures-container select{max-width:100%;}
}

/* Readable navigation on every page except the homepage. */
body:not(.home):not(.page-id-540) #masthead .menu-link { color: #111827 !important; }
body:not(.home):not(.page-id-540) #masthead .menu-link:hover,
body:not(.home):not(.page-id-540) #masthead .menu-link:focus-visible,
body:not(.home):not(.page-id-540) #masthead .current-menu-item > .menu-link,
body:not(.home):not(.page-id-540) #masthead .current-menu-ancestor > .menu-link { color: #8a4700 !important; }
body:not(.home):not(.page-id-540) #masthead .menu-toggle { color: #111827 !important; }
body:not(.home):not(.page-id-540) #masthead .menu-toggle svg { fill: currentColor; }

/* Upcoming Adventures: separate the menu and soften the page H1. */
body.page-id-7 #masthead { position: relative !important; top: auto !important; }
body.page-id-7 #post-7 > .entry-content > h1:first-child {
  font-family: Montserrat, sans-serif;
  font-size: clamp(22px, 3vw, 38px);
  font-weight: 500;
  line-height: 1.3;
  color: rgba(17, 24, 39, 0.8);
  text-align: center;
  letter-spacing: -0.02em;
  margin: 0 0 28px;
  padding: 24px 20px 0;
  box-sizing: border-box;
}

/* Adventure guide below the quest listings. */
body.page-id-7 .pp-adventure-guide { max-width: 1100px; margin: 64px auto 72px; padding: 0 24px; box-sizing: border-box; color: #374151; }
body.page-id-7 .pp-guide-intro { max-width: 760px; margin: 0 auto 32px; text-align: center; }
body.page-id-7 .pp-guide-eyebrow, body.page-id-7 .pp-guide-label { color: #8a4700; font-size: 12px; font-weight: 700; line-height: 1.5; letter-spacing: .1em; margin: 0 0 10px; }
body.page-id-7 .pp-guide-intro h2 { font-size: clamp(26px, 3vw, 36px); font-weight: 600; line-height: 1.25; color: #374151; margin: 0 0 16px; }
body.page-id-7 .pp-adventure-guide p, body.page-id-7 .pp-adventure-guide li { font-size: 16px; line-height: 1.75; }
body.page-id-7 .pp-guide-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 24px; }
body.page-id-7 .pp-guide-card { background: rgba(255,255,255,.85); border: 1px solid #e8e2cd; border-radius: 16px; padding: 28px; min-width: 0; }
body.page-id-7 .pp-guide-card h3 { font-size: 23px; line-height: 1.3; font-weight: 600; color: #111827; margin: 0 0 14px; }
body.page-id-7 .pp-guide-card p { margin: 0 0 16px; }
body.page-id-7 .pp-guide-card .pp-guide-label { font-size: 12px; line-height: 1.5; margin: 0 0 10px; }
body.page-id-7 .pp-guide-card ul { margin: 0; padding-left: 20px; }
body.page-id-7 .pp-guide-card li { margin-bottom: 6px; }
body.page-id-7 .pp-guide-card .pp-guide-best { padding-top: 16px; border-top: 1px solid #e8e2cd; margin-bottom: 0; font-size: 14px; }
body.page-id-7 .pp-adventure-guide img.emoji { width: 1em !important; height: 1em !important; display: inline !important; }
@media(max-width: 680px) { body.page-id-7 .pp-guide-grid { grid-template-columns: 1fr; gap: 16px; } body.page-id-7 .pp-adventure-guide { margin: 40px auto 48px; padding: 0 20px; } body.page-id-7 .pp-guide-card { padding: 24px; } }

/* About page: readable header, balanced content and retained photography. */
body.page-id-541 #masthead { position: relative !important; top: auto !important; }
body.page-id-541 #post-541 > .entry-header { display: none; }
body.page-id-541 .elementor-541 > .e-parent > .e-con-inner { max-width: 1100px; width: 100%; padding: 48px 24px !important; gap: 32px; box-sizing: border-box; }
body.page-id-541 .elementor-541 .elementor-element-43162c89 > .e-con-inner { padding: 64px 24px !important; justify-content: center; }
body.page-id-541 .elementor-541 .elementor-element-4669ede1 { width: 100%; padding: 0; }
body.page-id-541 .elementor-541 h1.elementor-heading-title { font-size: clamp(28px,3vw,38px); font-weight: 500; line-height: 1.3; text-align: center; color: rgba(255,255,255,.92); }
body.page-id-541 .elementor-541 .elementor-element-693e56a8 > .e-con-inner,
body.page-id-541 .elementor-541 .elementor-element-1603f506 > .e-con-inner { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); align-items: center; }
body.page-id-541 .elementor-541 .elementor-element-55aba155,
body.page-id-541 .elementor-541 .elementor-element-35981621,
body.page-id-541 .elementor-541 .elementor-element-22fb4421,
body.page-id-541 .elementor-541 .elementor-element-7f852b6e { width: 100% !important; min-width: 0; padding: 0; margin: 0; }
body.page-id-541 .elementor-541 .elementor-widget-divider { display: none; }
body.page-id-541 .elementor-541 h2.elementor-heading-title,
body.page-id-541 .elementor-541 h3.elementor-heading-title,
body.page-id-541 .elementor-541 h4.elementor-heading-title { font-size: clamp(24px,2.2vw,30px); font-weight: 600; line-height: 1.3; color: #374151; }
body.page-id-541 .elementor-541 .elementor-widget-text-editor,
body.page-id-541 .elementor-541 .elementor-icon-list-text { font-size: 16px; line-height: 1.8; color: #374151; text-align: left; }
body.page-id-541 .elementor-541 .elementor-widget-text-editor p { margin-bottom: 16px; }
body.page-id-541 .elementor-541 .elementor-element-20d9bf30 img { display: block; width: 100%; height: 350px; object-fit: cover; border-radius: 16px; box-shadow: none; }
body.page-id-541 .elementor-541 .elementor-element-1603f506 > .e-con-inner { padding-top: 0 !important; align-items: stretch; }
body.page-id-541 .elementor-541 .elementor-element-22fb4421,
body.page-id-541 .elementor-541 .elementor-element-7f852b6e { background: rgba(255,255,255,.85); border: 1px solid #e8e2cd; border-radius: 16px; padding: 28px; gap: 16px; }
body.page-id-541 .elementor-541 .elementor-icon-list-item { align-items: flex-start; padding-bottom: 16px; }
body.page-id-541 .elementor-541 .elementor-icon-list-icon svg { width: 18px; height: 18px; fill: #8a4700; margin-top: 5px; }
body.page-id-541 .elementor-541 .elementor-element-36324751 > .e-con-inner { max-width: 900px; padding-top: 0 !important; padding-bottom: 64px !important; }
body.page-id-541 .elementor-541 .elementor-element-7c0090a8 { width: 100%; padding: 32px; gap: 20px; background: rgba(255,255,255,.85); border: 1px solid #e8e2cd; border-radius: 16px; }
body.page-id-541 .elementor-541 .elementor-element-4b07ee4c,
body.page-id-541 .elementor-541 .elementor-element-44253d09 { text-align: center; }
body.page-id-541 .elementor-541 h6.elementor-heading-title { font-size: 20px; font-weight: 500; line-height: 1.5; color: #374151; }
body.page-id-541 .elementor-541 .elementor-button { background: #ed8b00; color: #111827; border-radius: 28px; padding: 16px 26px; }
@media(max-width:767px) {
 body.page-id-541 .elementor-541 .elementor-element-693e56a8 > .e-con-inner,
 body.page-id-541 .elementor-541 .elementor-element-1603f506 > .e-con-inner { grid-template-columns: 1fr; }
 body.page-id-541 .elementor-541 > .e-parent > .e-con-inner { padding: 32px 20px !important; gap: 24px; }
 body.page-id-541 .elementor-541 .elementor-element-43162c89 > .e-con-inner { padding: 48px 20px !important; }
 body.page-id-541 .elementor-541 .elementor-element-20d9bf30 img { height: 260px; }
 body.page-id-541 .elementor-541 .elementor-element-7c0090a8 { padding: 24px; }
}

/* Contact page: consistent heading, readable form and social icons. */
body.page-id-8 #masthead { position: relative !important; top: auto !important; }
body.page-id-8 #post-8 > .entry-header { display: none; }
body.page-id-8 .elementor-8 > .e-parent > .e-con-inner { max-width: 1100px; padding: 24px !important; width: 100%; box-sizing: border-box; }
body.page-id-8 .pp-contact { max-width: 1052px; margin: 0 auto 48px; color: #374151; }
body.page-id-8 .pp-contact-intro { text-align: center; margin: 0 0 36px; }
body.page-id-8 .pp-contact h1 { font-size: clamp(28px,3vw,38px); font-weight: 500; line-height: 1.3; color: rgba(17,24,39,.8); margin: 0 0 12px; }
body.page-id-8 .pp-contact-intro p { font-size: 18px; line-height: 1.6; margin: 0; }
body.page-id-8 .pp-contact-grid { display: grid; grid-template-columns: minmax(0,1.5fr) minmax(0,1fr); gap: 28px; align-items: start; }
body.page-id-8 .pp-contact-form, body.page-id-8 .pp-contact-info { background: rgba(255,255,255,.85); border: 1px solid #e8e2cd; border-radius: 16px; padding: 28px; min-width: 0; }
body.page-id-8 .pp-contact h2 { font-size: 25px; font-weight: 600; line-height: 1.3; color: #374151; margin: 0 0 24px; }
body.page-id-8 .pp-contact h3 { font-size: 20px; font-weight: 600; margin: 28px 0 14px; }
body.page-id-8 .pp-contact dl { margin: 0; }
body.page-id-8 .pp-contact dt { font-size: 14px; font-weight: 700; color: #111827; margin: 20px 0 4px; }
body.page-id-8 .pp-contact dt:first-child { margin-top: 0; }
body.page-id-8 .pp-contact dd { margin: 0; font-size: 16px; line-height: 1.7; overflow-wrap: anywhere; }
body.page-id-8 .pp-contact-info a { color: #8a4700; }
body.page-id-8 .pp-contact-socials { display: flex; flex-wrap: wrap; gap: 10px; }
body.page-id-8 .pp-contact-socials .pp-social { display: inline-flex; align-items: center; gap: 7px; padding: 10px 12px; border: 1px solid #e8e2cd; border-radius: 24px; font-size: 13px; font-weight: 600; line-height: 1.5; color: #111827; text-decoration: none; }
body.page-id-8 .pp-social:hover, body.page-id-8 .pp-social:focus-visible { background: #fef9e1; outline-offset: 3px; }
body.page-id-8 .pp-social-icon { width: 18px; height: 18px; flex: 0 0 18px; display: inline-block; background-color: currentColor; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-position: center; mask-position: center; -webkit-mask-size: contain; mask-size: contain; }
body.page-id-8 .pp-contact div.wpforms-container { margin: 0; }
body.page-id-8 .pp-contact .wpforms-field { padding: 0 0 18px; }
body.page-id-8 .pp-contact .wpforms-field-label { font-size: 14px; color: #111827; }
body.page-id-8 .pp-contact .wpforms-field input, body.page-id-8 .pp-contact .wpforms-field textarea { width: 100%; max-width: 100%; background: #fff; border: 1px solid #d1d5db; border-radius: 8px; font-size: 16px; box-sizing: border-box; }
body.page-id-8 .pp-contact .wpforms-field textarea { min-height: 140px; }
body.page-id-8 .pp-contact .wpforms-submit-container { padding-top: 0; }
body.page-id-8 .pp-contact button[type=submit] { border-radius: 28px; background: #ed8b00; color: #111827; padding: 14px 24px; font-weight: 600; border: 0; }
@media(max-width:767px) { body.page-id-8 .pp-contact-grid { grid-template-columns: 1fr; gap: 20px; } body.page-id-8 .pp-contact-form, body.page-id-8 .pp-contact-info { padding: 24px; } body.page-id-8 .elementor-8 > .e-parent > .e-con-inner { padding: 24px 20px !important; } }
